import pyomo.environ as pyo

DATA = {
    "products": ["thin", "stubby"],
    "profit": {"thin": 5, "stubby": 9},
    "shaping_minutes": {"thin": 50, "stubby": 30},
    "baking_minutes": {"thin": 90, "stubby": 150},
    "shaping_capacity": 3000,
    "baking_capacity": 4000,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # --- Sets ---
    model.PRODUCTS = pyo.Set(initialize=d["products"])

    # --- Variables ---
    # Number of jars of each type produced per week (integer, nonnegative).
    model.production = pyo.Var(
        model.PRODUCTS,
        within=pyo.NonNegativeIntegers,
    )

    # --- Objective: maximize total profit ---
    def objective_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.PRODUCTS)

    model.obj = pyo.Objective(rule=objective_rule, sense=pyo.maximize)

    # --- Constraints ---

    # Shaping time capacity per week.
    def shaping_capacity_rule(m):
        return sum(
            d["shaping_minutes"][p] * m.production[p] for p in m.PRODUCTS
        ) <= d["shaping_capacity"]

    model.shaping_capacity = pyo.Constraint(rule=shaping_capacity_rule)

    # Baking time capacity per week.
    def baking_capacity_rule(m):
        return sum(
            d["baking_minutes"][p] * m.production[p] for p in m.PRODUCTS
        ) <= d["baking_capacity"]

    model.baking_capacity = pyo.Constraint(rule=baking_capacity_rule)

    return model


